//! Go stub generation.

use crate::plugin::{snake_case, upper_camel, MethodKind, ProtoFile, Service};

pub fn generate(file: &ProtoFile) -> String {
    let mut out = String::new();
    out.push_str("// @generated by protoc-gen-qrpc. Do not edit.\n");
    out.push_str(
        "// Messages are generated by the native protobuf plugin; qRPC stubs move bytes.\n\n",
    );
    out.push_str(&format!("package {}\n\n", go_package(file)));
    out.push_str("import \"context\"\n\n");
    out.push_str("type ClientConn interface {\n");
    out.push_str("    Unary(ctx context.Context, method string, request []byte) ([]byte, error)\n");
    out.push_str("    NewStream(ctx context.Context, method string) (Stream, error)\n");
    out.push_str("}\n\n");
    out.push_str("type Stream interface {\n");
    out.push_str("    Send([]byte) error\n");
    out.push_str("    Recv() ([]byte, error)\n");
    out.push_str("    CloseSend() error\n");
    out.push_str("}\n\n");
    out.push_str("type Server interface {\n");
    out.push_str("    RegisterService(service string, handler any)\n");
    out.push_str("}\n\n");
    for service in &file.services {
        write_service(&mut out, service);
    }
    out
}

fn write_service(out: &mut String, service: &Service) {
    let client_name = format!("{}Client", upper_camel(&service.name));
    let server_name = format!("{}Server", upper_camel(&service.name));
    let register_name = format!("Register{}Server", upper_camel(&service.name));

    out.push_str(&format!("type {client_name} struct {{\n"));
    out.push_str("    conn ClientConn\n");
    out.push_str("}\n\n");
    out.push_str(&format!(
        "func New{client_name}(conn ClientConn) {client_name} {{\n"
    ));
    out.push_str(&format!("    return {client_name}{{conn: conn}}\n"));
    out.push_str("}\n\n");

    for method in &service.methods {
        let method_name = upper_camel(&method.name);
        match method.kind {
            MethodKind::Unary => {
                out.push_str(&format!(
                    "func (c {client_name}) {method_name}(ctx context.Context, request []byte) ([]byte, error) {{\n"
                ));
                out.push_str(&format!(
                    "    return c.conn.Unary(ctx, \"{}\", request)\n",
                    method.route
                ));
                out.push_str("}\n\n");
            }
            MethodKind::ServerStream => {
                out.push_str(&format!(
                    "func (c {client_name}) {method_name}(ctx context.Context, request []byte) (Stream, error) {{\n"
                ));
                out.push_str(&format!(
                    "    stream, err := c.conn.NewStream(ctx, \"{}\")\n",
                    method.route
                ));
                out.push_str("    if err != nil { return nil, err }\n");
                out.push_str(
                    "    if err := stream.Send(request); err != nil { return nil, err }\n",
                );
                out.push_str("    if err := stream.CloseSend(); err != nil { return nil, err }\n");
                out.push_str("    return stream, nil\n");
                out.push_str("}\n\n");
            }
            MethodKind::ClientStream | MethodKind::BidiStream => {
                out.push_str(&format!(
                    "func (c {client_name}) {method_name}(ctx context.Context) (Stream, error) {{\n"
                ));
                out.push_str(&format!(
                    "    return c.conn.NewStream(ctx, \"{}\")\n",
                    method.route
                ));
                out.push_str("}\n\n");
            }
        }
    }

    out.push_str(&format!("type {server_name} interface {{\n"));
    for method in &service.methods {
        let method_name = upper_camel(&method.name);
        match method.kind {
            MethodKind::Unary => {
                out.push_str(&format!(
                    "    {method_name}(context.Context, []byte) ([]byte, error)\n"
                ));
            }
            _ => {
                out.push_str(&format!(
                    "    {method_name}(context.Context, Stream) error\n"
                ));
            }
        }
    }
    out.push_str("}\n\n");
    out.push_str(&format!(
        "func {register_name}(server Server, handler {server_name}) {{\n"
    ));
    out.push_str(&format!(
        "    server.RegisterService(\"{}\", handler)\n",
        service.full_name
    ));
    out.push_str("}\n\n");
}

fn go_package(file: &ProtoFile) -> String {
    let from_package = file.package.rsplit('.').next().unwrap_or("");
    let package = if from_package.is_empty() {
        file.stem.as_str()
    } else {
        from_package
    };
    let package = snake_case(package);
    if package.is_empty() {
        "qrpcstub".to_string()
    } else {
        package
    }
}
